import{_ as t,o as r,c as a,ah as o}from"./chunks/framework.CRsDMGp2.js";const h=JSON.parse('{"title":"Guide — Chef de projet & Collaborateurs","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/chef-projet-collaborateurs.md","filePath":"src/guide/chef-projet-collaborateurs.md"}'),n={name:"guide/chef-projet-collaborateurs.md"};function l(s,e,i,u,c,d){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="guide-—-chef-de-projet-collaborateurs" tabindex="-1">Guide — Chef de projet &amp; Collaborateurs <a class="header-anchor" href="#guide-—-chef-de-projet-collaborateurs" aria-label="Permalink to &quot;Guide — Chef de projet &amp; Collaborateurs&quot;">​</a></h1><p>Piloter et exécuter les projets au quotidien.</p><p>Ce guide couvre deux profils proches : le <strong>Chef de projet</strong>, qui pilote un projet de bout en bout, et les <strong>Collaborateurs / Consultants</strong> (7 métiers), qui exécutent les missions techniques qui leur sont confiées.</p><h2 id="partie-a-—-chef-de-projet" tabindex="-1">Partie A — Chef de projet <a class="header-anchor" href="#partie-a-—-chef-de-projet" aria-label="Permalink to &quot;Partie A — Chef de projet&quot;">​</a></h2><h3 id="creer-et-piloter-un-projet" tabindex="-1">Créer et piloter un projet <a class="header-anchor" href="#creer-et-piloter-un-projet" aria-label="Permalink to &quot;Créer et piloter un projet&quot;">​</a></h3><ul><li>Créez un nouveau projet depuis <strong>Projets &gt; Nouveau projet</strong> : client, chef de projet, apporteur d&#39;affaires éventuel et <strong>type de projet</strong>. Le type choisi pré-remplit automatiquement les phases et jalons par défaut de la méthodologie correspondante (huit types disponibles : Site web / présence digitale, Application ou plateforme sur mesure, Conseil en transformation numérique, Architecture des systèmes d&#39;information, Cloud &amp; Infrastructures, Cybersécurité, Intelligence artificielle &amp; données, Formation).</li><li>Ajustez les phases et jalons pré-remplis si besoin (renommage, réordonnancement, pourcentage de facturation de chaque jalon facturable) depuis l&#39;onglet <strong>Suivi</strong> de la fiche projet.</li><li>Constituez l&#39;équipe projet depuis l&#39;onglet <strong>Équipe</strong> et affectez les tâches, y compris à des partenaires externes — précisez leur mode de rémunération (forfait, pourcentage de jalon ou taux journalier).</li><li>Suivez l&#39;avancement global via les vues <strong>Gantt</strong> (par phase et jalon) ou <strong>Kanban</strong> (par statut de tâche).</li></ul><h3 id="jalons-et-facturation" tabindex="-1">Jalons et facturation <a class="header-anchor" href="#jalons-et-facturation" aria-label="Permalink to &quot;Jalons et facturation&quot;">​</a></h3><ul><li>À la validation d&#39;un jalon <strong>non facturable</strong>, ajoutez un compte-rendu visible par le client (et, quand c&#39;est pertinent, un lien de démo vers une version fonctionnelle du projet à cette étape).</li><li>La validation d&#39;un jalon <strong>facturable</strong> enregistre le montant dû, calculé sur son pourcentage de facturation. Signalez-le à l&#39;administrateur, qui se charge de générer la facture correspondante.</li><li>En cas de facture impayée au-delà du délai convenu, vous pouvez suspendre ou lever la suspension de l&#39;accès au projet, concurremment à l&#39;administrateur.</li></ul><h3 id="avenants-et-cloture" tabindex="-1">Avenants et clôture <a class="header-anchor" href="#avenants-et-cloture" aria-label="Permalink to &quot;Avenants et clôture&quot;">​</a></h3><ul><li>Initiez une demande d&#39;avenant depuis l&#39;onglet <strong>Avenants</strong> si le périmètre, le délai ou le budget du projet doit évoluer. L&#39;administrateur formalise ensuite le document, qui part en signature électronique auprès du client ; l&#39;impact budgétaire ne s&#39;applique qu&#39;une fois l&#39;avenant signé.</li><li>À la clôture du projet, cochez l&#39;éventuelle éligibilité <strong>NextBoxx</strong> et ajoutez une note libre si le projet peut servir de cas réel pour les formations internes.</li></ul><h2 id="partie-b-—-collaborateurs-consultants" tabindex="-1">Partie B — Collaborateurs / Consultants <a class="header-anchor" href="#partie-b-—-collaborateurs-consultants" aria-label="Permalink to &quot;Partie B — Collaborateurs / Consultants&quot;">​</a></h2><p>Le tronc commun du parcours est identique quel que soit votre métier (Consultant en transformation numérique, Développeur, Architecte SI, Expert Cloud &amp; Infrastructures, Expert Cybersécurité, Expert IA &amp; Données, Formateur interne) — seul le livrable attendu change.</p><h3 id="vos-missions" tabindex="-1">Vos missions <a class="header-anchor" href="#vos-missions" aria-label="Permalink to &quot;Vos missions&quot;">​</a></h3><ul><li>Consultez les tâches qui vous sont assignées, tous projets confondus, depuis votre tableau de bord ou l&#39;onglet <strong>Tâches</strong> d&#39;un projet.</li><li>Mettez à jour leur avancement (à faire, en cours, terminée) et déposez vos livrables directement depuis leur fiche.</li><li>Échangez avec le chef de projet et, selon le contexte, le client via la messagerie intégrée du projet.</li></ul>',14)])])}const m=t(n,[["render",l]]);export{h as __pageData,m as default};
